    private void HandleCardClick(ModuleItem item)
    {
        if (!item.IsSoon)
        {
            NavManager.NavigateTo(item.Route);
            return;
        }

        if (item.Route == "/hoc-ba/khoi-tao-hoc-ba")
        {
            NavManager.NavigateTo(item.Route);
        }
    }

